static int timer_list_open(struct inode *inode, struct file *file)
{
	return seq_open_private(file, &timer_list_sops,
			sizeof(struct timer_list_iter));
}

static const struct proc_ops timer_list_proc_ops = {
	.proc_open	= timer_list_open,
	.proc_read	= seq_read,
	.proc_lseek	= seq_lseek,
	.proc_release	= seq_release_private,
};

static int __init init_timer_list_procfs(void)
{
	struct proc_dir_entry *pe;

	pe = proc_create("timer_list", 0400, NULL, &timer_list_proc_ops);
	if (!pe)
		return -ENOMEM;
	return 0;
}

